<script module lang="ts">
/**
 * Title, description and actions at the top of a working page (`design/components/page-header.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/page-header.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotOutlet, SlotScope, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/page-header.module.css'
import Inline from '../layout/Inline.svelte'

export interface PageHeaderProps {
  /**
   * Vocabulary controls only: one primary, and the rest less prominent.
   */
  actions?: Snippet
  description?: string
  title: string
  /**
   * An InlineEdit of the title, drawn beside the `<h1>`, with `title` as its `value` and
   * `size="lg"`. PageHeader hands it `valueHidden`, because the `<h1>` draws the value. The app
   * gives it its label, its handlers and, for a save that waits for a server, `editing`,
   * `pending` and `error`.
   */
  titleEdit?: Snippet
}
</script>

<script lang="ts">
let { actions, description, title, titleEdit }: PageHeaderProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get titleEdit() {
    return titleEdit
  },
}
const titleEditScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({ valueHidden: true }),
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<header class={styles.header} data-member="page-header"
    ><div class={styles.text}
      >{#if slots.titleEdit
        }<div class={styles.titleRow}
          ><h1 class={styles.title}>{title}</h1
          ><div class={styles.titleEdit}
            ><SlotOutlet scope={titleEditScope} snippet={titleEdit}
          /></div
        ></div
      >{:else
        }<h1 class={styles.title}>{title}</h1
      >{/if
      }{#if description !== undefined}<p class={styles.description}>{description}</p>{/if
    }</div
    >{#if slots.actions}<Inline gap={3} wrap={true}>{@render actions?.()}</Inline>{/if
  }</header
>{/if
}{@render joined.end?.()}
